/* Deterministic review fixtures only. No API, identity, storage or product writes. */
const pages=['list','create','configuration','review','entries','roster','schedule','match'];
const variants={list:['populated','empty','long'],create:['individual','team','validation','dirty'],configuration:['preparing','ready','running','saved'],review:['complete','incomplete','publishing'],entries:['admitted','waiting','empty','mandatory','locked','running','cancel','admit','add','duplicate','search-error','row-error'],roster:['editable','empty','frozen','cancelled','add','search-error','duplicate','history'],schedule:['blocked','draft','stale','published','withdraw','withdraw-error','withdrawn','running','odd'],match:['individual','chosen','team-preparation','team-incomplete','team-ready','team-dirty','start-confirm','in-play','team-in-play','resolved','team-resolved']};
const common=['loading','error','conflict','busy','permission'];
const states=pages.flatMap(p=>[...variants[p],...common].map(v=>`${p}:${v}`));
let key=new URLSearchParams(location.search).get('state')||'schedule:running';if(!states.includes(key))key='schedule:running';
const [page,state]=key.split(':');const team=state.startsWith('team')||page==='roster';
const A=team?'River Falcons':'Sam Reed',B=team?'North Stars':'Jamie Brook';
const title=team?'Saturday Team League':'Saturday Open';
const running=['running','individual','chosen','in-play','team-in-play','resolved','team-resolved','team-preparation','team-incomplete','team-ready','team-dirty','start-confirm'].includes(state);
const badge=(s,t='')=>`<span class="badge ${t}">${s}</span>`;
const link=(text,p,v,cls='button')=>`<a class="${cls}" href="?state=${p}:${v}">${text}</a>`;
const btn=(text,act='',cls='',disabled=false)=>`<button type="button" class="${cls}" ${act?`data-go="${act}"`:''} ${disabled?'disabled':''}>${text}</button>`;
const notice=(h,t,error=false,extra='')=>`<section class="notice ${error?'error':''}" role="${error?'alert':'status'}"><strong>${h}</strong><p>${t}</p>${extra}</section>`;
const draftPage=['create','review'].includes(page);
const labels=()=>`<div class="labels">${badge(draftPage?'Draft':'Published')}${badge(draftPage?'Registration not open':(running||page==='schedule'?'Registration closed':'Registration open'))}${badge(running?'Running':'Preparing',running?'info':'')}</div>`;
const field=(label,value='',type='text',help='',locked=false)=>`<label class="field">${label}<input type="${type}" value="${value}" ${locked?'readonly':''}><small class="muted">${help}</small></label>`;
const history=(label='Publication history · 1')=>`<details><summary>${label}</summary><p class="meta numeric">Revision 1 · 21 November 2026, 10:00 · Europe/Madrid</p><p class="meta">Retained evidence. Reason: Updated attendance.</p></details>`;
function header(){if(page==='list')return `<div class="summary"><div><h1>Tournaments</h1><p class="muted">Northside Gaming · your organising workspace</p></div>${link('Create tournament','create','individual','button primary')}</div>`;return `${link(page==='match'?'Back to schedule':'Back to tournaments',page==='match'?'schedule':'list',page==='match'?'running':'populated','back')}<div class="title"><h1>${page==='create'?'Create tournament':page==='review'?'Review before publishing':title}</h1>${page==='review'?'':labels()}</div><p class="meta">${page==='review'?'Read-only configuration summary · '+title:'Strategy · '+(team?'Team':'Individual')+' · 21 November 2026, 10:00 · Europe/Madrid'}</p>${page==='review'?labels():''}${['create','review'].includes(page)?'':`<nav class="tabs" aria-label="Tournament sections">${['configuration','entries','schedule'].map(p=>`<a href="?state=${p}:${p==='configuration'?'running':p==='entries'?'admitted':'running'}" ${(page==='match'?'schedule':page)===p?'aria-current="page"':''}>${p[0].toUpperCase()+p.slice(1)}</a>`).join('')}</nav>`}`}
function list(){if(state==='empty')return `<section class="panel"><h2>No tournaments yet</h2><p>Create a draft, then complete its publication requirements.</p>${link('Create tournament','create','individual','button primary')}</section>`;return `<div class="rows">${['Saturday Open','Saturday Team League','Winter Draft Cup'].map((n,i)=>`<article class="row"><div><h2 class="long-name">${state==='long'?n+' · Regional invitational championship with an extended tournament name':n}</h2><p class="meta numeric">21 November 2026 · Europe/Madrid</p><p class="numeric">${i===2?'Capacity · 16 individual entries':'4 of 4 entries admitted'}</p><div class="labels">${badge(i===2?'Draft':'Published')}${badge(i===2?'Registration not open':'Registration closed')}${badge(i===0?'Running':'Preparing',i===0?'info':'')}</div></div><div class="actions">${i===2?link('Continue draft','create','individual'):link('View schedule','schedule','running')}${i!==2?link('Entries','entries','admitted'):''}${i!==2?link('Configuration','configuration','running','button quiet'):''}</div></article>`).join('')}</div>`}
function configuration(){const lock=state==='running';return `${state==='saved'?notice('Saved configuration','The saved values below are current.'):''}${page==='configuration'?`<section class="panel summary"><div><h2>${lock?'Competition running':'Prepare the competition'}</h2><p>${lock?'Field and schedule fixed at start. Descriptive details remain editable.':'Registration, eligible entries and a published schedule are required before start.'}</p></div><div class="actions">${link('View schedule','schedule',lock?'running':'blocked')}${lock?'':btn('Start competition','configuration:running','primary',state!=='ready')}</div></section>`:''}${state==='validation'?notice('Correct 1 field to save','Nothing was saved. Enter a tournament title.',true):''}<form class="panel" id="config"><h2>Tournament details</h2><p class="muted">${lock?'Competition settings below are fixed.':'Save a draft before all publication requirements are complete.'}</p><div class="form-grid">${field('Title',page==='create'?'':title)}${field('Game / variant','Strategy')}${field('Entry kind',team?'Team':'Individual','text',lock?'Fixed when competition started.':'Each entry occupies one place.',lock)}${field('Capacity',4,'number',lock?'Fixed when competition started.':'Number of admitted entries.',lock)}</div>${team?`<h2>Team structure</h2><div class="form-grid">${field('Minimum roster size',5,'number','',lock)}${field('Maximum roster size',7,'number','',lock)}${field('Active players per side',5,'number','',lock)}</div>`:''}<h2>Dates and location</h2><div class="form-grid">${field('Planned start','2026-11-21T10:00','datetime-local')}${field('Reference time zone','Europe/Madrid')}${field('Venue','Northside Hall')}${field('Check-in','Optional','text',lock?'Fixed when competition started.':'Required before start when mandatory.',lock)}</div><p class="meta">Single round-robin · Win 3 · Draw 1 · Loss 0. Times use the reference time zone.</p><div class="actions">${btn(page==='create'?'Save draft':'Save changes','configuration:saved','primary')}${page==='create'?link('Review and publish','review','complete'):''}${link('Leave without saving','create','dirty','quiet')}</div></form>`}
function review(){return `${state==='incomplete'?notice('Complete configuration before publishing','A title is missing. Return to configuration.',true):''}<section class="panel"><h2>Tournament details</h2><p>${title} · Individual · 4 entries</p><h2>Competition profile</h2><p>Single round-robin · Win 3 · Draw 1 · Loss 0 · shared positions</p><h2>Dates and location</h2><p class="numeric">21 November 2026, 10:00 · Europe/Madrid · Northside Hall</p><h2>Admission and visibility</h2><p>Automatic · Optional check-in · Public</p><p><strong>Publishing keeps registration not open.</strong> It creates no entries, pairings or play. A published tournament cannot be unpublished.</p><div class="actions">${btn(state==='publishing'?'Publishing…':'Publish tournament','configuration:preparing','primary',state!=='complete')}${link('Edit configuration','create','individual')}</div></section>`}
function entries(){return `<section class="summary"><div><h2 class="numeric">${state==='empty'?'0 of 8':'4 of 4'} individual entries</h2><p class="muted">${state==='waiting'?'Manual admission · 2 pending your decision':'Automatic admission · 1 waiting for a slot'}</p></div>${['locked','running'].includes(state)?'':btn('Add player','entries:add','primary')}</section>${state==='running'?notice('Entries are read-only','The competition has started. Continue competition work in Schedule.',false,link('View schedule','schedule','running')):state==='locked'?notice('Field locked','Withdraw the published schedule before changing entries.',false,link('Open schedule','schedule','published')):state==='mandatory'?notice('1 entry needs check-in','Check Sam Reed in, or review an absence before preparing the schedule.'):''}${state==='empty'?`<section class="panel"><h2>No entries yet</h2><p>Admitted and waiting entries will appear here.</p></section>`:`<section><h2>${state==='waiting'?'Waiting · 2':'Admitted · 4'}</h2><div class="rows">${['Sam Reed','Jamie Brook','Alex Kim','Casey Moss'].slice(0,state==='waiting'?2:4).map((n,i)=>`<article class="row"><div><h3>${n}</h3><p class="meta">${state==='waiting'?'Admission pending':i===0?'Check-in pending':'Checked in'}</p>${state==='row-error'&&i===0?'<p class="error-text">Check-in did not change. Try again.</p>':''}</div><div class="actions">${['locked','running'].includes(state)?'':btn(state==='waiting'?'Admit':'Check in',state==='waiting'?'entries:admit':'entries:admitted')}${['locked','running'].includes(state)?'':btn('Cancel entry','entries:cancel')}</div></article>`).join('')}</div></section>${history('Cancelled · 1')}`}`}
function schedule(){const draft=['draft','stale','withdrawn'].includes(state);return `<section class="summary"><div><h2 class="numeric">4 players · 3 rounds · 6 matches</h2><div class="labels">${badge(state==='blocked'?'No draft':draft?'Draft':'Published · revision 1',draft||state==='blocked'?'':'success')}</div><p class="meta">Single round-robin · Admission order</p></div><div class="actions">${draft?btn('Publish','schedule:published','primary',state==='stale'):state==='published'?btn('Withdraw','schedule:withdraw'):''}</div></section>${state==='blocked'?notice('Check-in required','One admitted entrant is pending. Resolve attendance before generating a draft.',false,link('Open entries','entries','mandatory')):state==='stale'?notice('Field changed after generation','Regenerate the draft before publishing.',true,btn('Regenerate','schedule:draft','primary')):state==='running'?notice('Schedule fixed by start','Matches may be played in any round. The schedule cannot be withdrawn.'):''}${state==='blocked'?'':`<section><h2>Round 1</h2><div class="rows">${[[A,B,'In play',''],['Alex Kim','Casey Moss','Resolved','Alex Kim won']].map(([a,b,s,r])=>`<article class="row"><div><h3>${a} <span class="muted">vs</span> ${b}</h3><p>${state==='running'?(r||'No result recorded'):'No result recorded'}</p></div><div class="actions">${badge(draft?'Draft pairing':state==='running'?s:'Scheduled',state==='running'?(s==='In play'?'info':'success'):'')}${!draft&&state==='running'?link('View match','match',r?'resolved':'in-play'):''}</div></article>`).join('')}</div>${state==='odd'?'<p class="meta">Rest: Morgan Vale · no points</p>':''}</section><section><h2>Round 2</h2><div class="rows"><article class="row"><div><h3>Sam Reed vs Alex Kim</h3><p>No result recorded</p></div><div class="actions">${badge('Scheduled')}${state==='running'?link('View match','match','individual'):''}</div></article></div></section>`}${state==='withdrawn'?history():''}`}
function lineup(name,i){return `<section class="panel"><h2>${name} · lineup</h2><p class="meta">${state==='team-preparation'?'0':state==='team-incomplete'&&i?'4':'5'} of 5 selected · frozen roster</p><div class="players">${['Alex Kim','Casey Moss','Drew Lane','Eli Hart','Frankie Cole'].map((n,j)=>`<label><input type="checkbox" ${state==='team-preparation'||(state==='team-incomplete'&&i&&j===4)?'':'checked'}>${n}${i?' · North':''}</label>`).join('')}</div><div class="actions">${btn('Save lineup','match:team-ready','',state==='team-preparation'||(state==='team-incomplete'&&i===1))}${link('Discard changes','match','team-preparation')}</div></section>`}
function result(){const resolved=state.includes('resolved');return `<section class="panel"><div class="title"><h2>Result</h2>${resolved?badge('Resolved','success'):''}</div>${resolved?`<p><strong>${new URLSearchParams(location.search).get('outcome')==='draw'?'Draw':new URLSearchParams(location.search).get('outcome')==='second'?B+' won':A+' won'} · played</strong></p><p class="meta numeric">Recorded 21 November 2026, 11:20 · Europe/Madrid</p><p class="meta">This result is read-only.</p>`:`<fieldset class="outcomes"><legend>Choose the outcome</legend>${[A+' wins','Draw',B+' wins'].map((n,i)=>`<label><input type="radio" name="outcome" ${state==='chosen'&&i===0?'checked':''}>${n}</label>`).join('')}</fieldset><div class="actions" style="margin-top:24px">${btn('Record result','match:resolved&outcome=first','primary',state!=='chosen')}<span class="muted" id="choice-help">${state==='chosen'?'Ready to record.':'Choose an outcome first.'}</span></div>`}</section>`}
function match(){const prep=['team-preparation','team-incomplete','team-ready','team-dirty','start-confirm'].includes(state);return `<section class="summary"><div><h2>Round 1 · ${A} vs ${B}</h2><p class="meta">${team?'Direct team match · 5 active players per side':'Individual match'}</p></div>${badge(prep?'Scheduled':state.includes('resolved')?'Resolved':'In play',prep?'':'info')}</section>${prep?lineup('River Falcons',0)+lineup('North Stars',1)+`<section class="panel"><h2>Start match</h2><p>Starting locks both saved lineups.</p>${btn('Start match','match:start-confirm','primary',state==='team-preparation'||state==='team-incomplete')}</section>`:result()+`${team?`<section><h2>Locked lineups</h2><details class="panel"><summary>River Falcons · 5 starters, 2 reserves</summary><p>Alex Kim · Casey Moss · Drew Lane · Eli Hart · Frankie Cole</p><p class="meta">Revision 1 · locked at match start</p></details><details class="panel"><summary>North Stars · 5 starters, 2 reserves</summary><p>Indy Shaw · Jordan Pike · Kai Burns · Lee Marsh · Morgan Hale</p><p class="meta">Revision 1 · locked at match start</p></details></section>`:''}`}`}
function roster(){return `<section class="panel"><h2>River Falcons · roster</h2><p>5 to 7 players · ${state==='empty'?'0':'5'} recorded</p>${['frozen','cancelled'].includes(state)?notice('Read only',state==='frozen'?'Frozen at competition start; membership cannot change.':'This cancelled entry retains its roster evidence.'):''}${state==='empty'?'<p>No players yet. Add players to prepare this team.</p>':`<div class="rows">${['Alex Kim','Casey Moss','Drew Lane'].map(n=>`<article class="row"><div><strong>${n}</strong></div>${['frozen','cancelled'].includes(state)?'':btn('Remove','roster:editable')}</article>`).join('')}</div>`}${['frozen','cancelled'].includes(state)?'':`<div class="actions">${btn('Add player','roster:add','primary')}</div>`}${state==='history'?history('Roster history · 3'):''}</section>`}
function content(){if(state==='permission')return notice('Workspace unavailable','Your access must be checked again. No tournament records are shown.',true,link('Return to tournaments','list','populated'));if(state==='loading')return `<section class="panel" role="status" aria-busy="true"><h2>Loading ${page}…</h2><p>Please wait while current records are loaded.</p></section>`;if(state==='error')return notice('This page could not be loaded','No records are shown. Retry loads all required page data.',true,link('Try again',page,variants[page][0]));return `${state==='conflict'?notice('This record changed elsewhere','Your request did not apply. Review the latest version before trying again.',true,link('Reload latest',page,variants[page][0])):''}${state==='busy'?notice('Request in progress','Please wait. Repeated submission is unavailable.'):''}${({list,create:configuration,configuration,review,entries,roster,schedule,match})[page]()}`}
function overlay(){let h='',body='',action='',drawer=false;if(['add','search-error','duplicate'].includes(state)){drawer=true;h=page==='roster'?'Add player':'Add entrant';body=`<p>Choose an existing organisation guest or create a new alias.</p><div class="actions">${btn('Choose existing')}${btn('Create new')}</div>${field('Search by name','Alex')}${state==='search-error'?notice('Search failed','Your query is kept. Retry the same name.',true,link('Try again',page,'add')):state==='duplicate'?notice('Possible duplicate','A guest with this name exists. No identities have been merged.'):''}<div class="rows"><article class="row"><div><strong>Alex Kim</strong><p class="meta">Existing guest</p></div>${btn('Add',page+':'+(page==='roster'?'editable':'admitted'))}</article><article class="row"><div><strong>Alexander Vale</strong><p class="meta">Existing guest</p></div>${btn('Add',page+':'+(page==='roster'?'editable':'admitted'))}</article></div>`;}else if(state==='cancel'){h='Cancel Sam Reed’s entry?';body='<p>This entry cannot be restored. Entering again creates a new entry at the back of the queue.</p>'+notice('Effect on the waiting list','Alex Kim, first in the capacity queue, will be admitted automatically.');action=btn('Confirm cancellation','entries:admitted','danger-button');}else if(state==='admit'){h='Admit outside queue order?';body=field('Reason (required)','','text','Private to the organisation.');action=btn('Admit','entries:admitted','primary');}else if(state.startsWith('withdraw')){if(state==='withdrawn')return '';h='Withdraw revision 1?';body='<p>The revision stays in history; pairings return as the draft and the field unlocks.</p>'+field('Reason (required)','','text','Private to the organisation. At most 500 characters.')+(state==='withdraw-error'?'<p class="error-text" role="alert">Error: Enter a reason.</p>':'');action=btn('Withdraw','schedule:withdrawn','danger-button');}else if(state==='start-confirm'){h='Start this match?';body='<p>Starting locks both saved five-player lineups. They cannot change once play starts.</p>';action=btn('Start match','match:team-in-play','primary');}else if(state==='team-dirty'||state==='dirty'){h='Leave without saving your changes?';body='<p>Your unsaved selections will be lost. Nothing is submitted by leaving.</p>';action=btn('Leave without saving','list:populated','danger-button');}if(!h)return '';return `<dialog class="${drawer?'drawer':''}" aria-labelledby="dialog-title"><h2 id="dialog-title">${h}</h2>${body}<div class="actions" style="margin-top:24px">${action}<button type="button" data-close autofocus>${drawer?'Back to '+(page==='roster'?'roster':'entries'):state.startsWith('withdraw')?'Keep it published':state==='cancel'?'Keep entry':'Stay on this page'}</button></div></dialog>`}
const options=pages.map(p=>`<optgroup label="${p}">${states.filter(k=>k.startsWith(p+':')).map(k=>`<option value="${k}" ${k===key?'selected':''}>${k.split(':')[1]}</option>`).join('')}</optgroup>`).join('');
document.querySelector('#app').innerHTML=`<div class="review"><strong>Visual proposal · not approved</strong><label>Review state <select id="review-state">${options}</select></label><a href="tournament-admin-ux.md">State inventory and review notes</a><p>No API or persistent data. All actions are simulated.</p></div><div class="shell"><aside class="rail"><a class="brand" href="?state=list:populated">HERALD<span>.</span></a><div class="organisation"><strong>Northside Gaming</strong><small>Organisation · Owner</small></div><nav aria-label="Workspace"><a class="current" href="?state=list:populated">Tournaments</a></nav></aside><main id="main"><div class="workspace"><span>Organiser workspace</span><span>Alex Morgan · Owner</span></div>${state==='permission'?'':header()}<div class="stack">${content()}</div><p class="status-note">Review fixture · ${key} · XP-01 organiser operations. Domain behaviour remains subject to the implemented specifications.</p></main></div>${overlay()}`;
document.querySelector('#review-state').addEventListener('change',e=>location.search='?state='+e.target.value);
document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',()=>location.search='?state='+el.dataset.go));
document.querySelectorAll('input[name=outcome]').forEach(el=>el.addEventListener('change',()=>{const b=document.querySelector('.outcomes + .actions button');b.disabled=false;b.dataset.go='match:'+ (team?'team-resolved':'resolved')+'&outcome='+(['first','draw','second'][[...document.querySelectorAll('input[name=outcome]')].indexOf(el)]);b.onclick=()=>location.search='?state='+b.dataset.go;document.querySelector('#choice-help').textContent='Ready to record.';}));
document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>e.preventDefault()));
if(state==='conflict'){document.querySelectorAll('main button,main input,main select').forEach(el=>el.disabled=true);}
if(state==='busy'){document.querySelectorAll('main button,main input,main select').forEach(el=>el.disabled=true);document.querySelector('main').setAttribute('aria-busy','true');}
const dialog=document.querySelector('dialog');if(dialog){dialog.showModal();document.querySelector('[data-close]').onclick=()=>{dialog.close();if(!['team-dirty','dirty'].includes(state))location.search='?state='+page+':'+variants[page][0];};dialog.addEventListener('cancel',()=>{if(!['team-dirty','dirty'].includes(state))location.search='?state='+page+':'+variants[page][0];});}
